export function syllabusById(id) { return SYLLABI.find((s) => s.id === id) || null; }

// writing_cards rows for a child for a whole syllabus (lesson_tag carries the
// syllabus id so lists stay separate; pinyin/sentence derived/empty).
export function buildSyllabusRows(childId, syllabusId) {
  const s = syllabusById(syllabusId);
  if (!s) return [];
  const rows = [];
  s.lessons.forEach((lesson, li) => {
    lesson.chars.forEach((ch, wi) => {
      rows.push({ child_id: childId, word: ch, level: s.level,
        lesson_tag: `${s.id}::${lesson.tag}`, lesson_seq: li + 1, word_seq: wi + 1 });
    });
  });
  return rows;
}

